head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > getKeyCode]<br/>키 이벤트에서 컴포넌트 객체와 이벤트 객체를 전달받아 keyCode 값 또는 유니코드 값을 반환합니다.<br/>keyCode 가 발생하는 경우에는 keyCode 값을, keyCode 가 발생하지 않는 경우에는 유니코드 값을 10진수 형태로 반환합니다.",
    "validation" : [
        "component(필수) 파라미터로 키 이벤트가 발생한 WebSquare 컴포넌트 객체를 설정할 수 있어야 합니다.",
        "e(필수) 파라미터로 키보드 이벤트 객체를 설정할 수 있어야 합니다.",
        "keyCode 값 또는 유니코드 값을 반환해야 합니다.",
        "IME 입력(한글 등) 중에는 keyCode 가 229 로 전달될 수 있으며, 이 경우 유니코드 값을 반환해야 합니다.",
    ]
}



// comp 생성
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="target1(input) 에서 키 입력 시 getKeyCode 결과 출력"', '', 'label1');

    let ns = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    let strInput = '<w2:input ' + ns + ' ev:onkeydown="scwin.target1_onkeydown" style="width:200px;"></w2:input>';
    await $p.dynamicCreate('target1', 'input', strInput, grp_comp);
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 동적 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.target1_onkeydown = function (e) {
    let keyCode = WebSquare.util.getKeyCode(target1, e);

    let result = [];
    result.push("getKeyCode : " + keyCode);
    result.push("e.keyCode : " + e.keyCode);
    result.push("e.key : " + e.key);
    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
